-- =====================================================================
-- NovaBank sample data. Safe to load into an empty NOVABANK database
-- created with 01-schema.sql. Timestamps are relative to load time so
-- dashboards always show recent activity.
--
-- Demo logins (all passwords are BCrypt hashed):
--   ADMIN     admin@novabank.dev        / Admin@123
--   ADMIN     ops@novabank.dev          / Admin@123
--   CUSTOMER  john.carter@example.com   / Password@123
--   CUSTOMER  priya.sharma@example.com  / Password@123
--   CUSTOMER  (any other example.com user) / Password@123
--   LOCKED    david.okafor@example.com  (cannot log in until an admin unlocks him)
-- =====================================================================

-- Users
ALTER TABLE NB_AUTH.USERS ALTER COLUMN ID RESTART WITH 1000;

-- Accounts (balances equal opening deposit plus the completed transactions below)
ALTER TABLE NB_ACCT.ACCOUNTS ALTER COLUMN ID RESTART WITH 1000;

-- Transactions
ALTER TABLE NB_TXN.TRANSACTIONS ALTER COLUMN ID RESTART WITH 1000;

COMMIT;
